using Gemm = cutlass::gemm::device::Gemm<
  int4b_t,                          // ElementA
  cutlass::layout::RowMajor,         // LayoutA
  int4b_t,                          // ElementB
  cutlass::layout::ColumnMajor,      // LayoutB
  int32_t,                          // ElementC (accumulator)
  cutlass::layout::RowMajor,         // LayoutC
  int32_t                           // ElementAccumulator
>;

